.badge {
  /* Sizes to its label, never to its container. `display: inline-flex` is not
     enough: as a flex or grid child with the default `stretch`, the cross size
     is set by the parent and the pill runs the full width — a badge that reads
     as a text input, which is exactly how it shipped on the patterns screen
     (measured 2026-08-22: 219px of pill around 48px of text). An explicit
     inline-size opts out of stretch, in both axes' worth of cases. */
  inline-size: fit-content;
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-2xs) var(--space-3);
  border: 1px solid transparent;
  border-radius: var(--radius-full);
  font-size: var(--font-sm);
  font-weight: var(--font-weight-regular);
  line-height: var(--leading-snug);
  white-space: nowrap;
}
/* md — matches a small button: same height + horizontal padding. */
.badge[data-size="md"] {
  height: var(--control-height-sm);
  padding-inline: var(--space-3);
}
/* Default style = solid (bold colored tag). */
.badge[data-tone="neutral"] { background: transparent;       color: var(--muted-foreground); border-color: var(--border); }
.badge[data-tone="primary"] { background: var(--primary);    color: var(--primary-foreground); }
.badge[data-tone="success"] { background: var(--success); color: var(--success-foreground); }
.badge[data-tone="warning"] { background: var(--warning); color: var(--warning-foreground); }
.badge[data-tone="danger"]  { background: var(--destructive);  color: var(--destructive-foreground); }
.badge[data-tone="ai"]      { background: var(--ai);           color: var(--ai-foreground); }

/* Soft fill — light tinted bg + saturated text. shadcn-style. */
.badge[data-fill="soft"][data-tone="primary"] { background: var(--primary-soft);  color: var(--primary-soft-foreground); }
.badge[data-fill="soft"][data-tone="success"] { background: var(--success-soft);  color: var(--success-soft-foreground); }
.badge[data-fill="soft"][data-tone="warning"] { background: var(--warning-soft); color: var(--warning-soft-foreground); }
.badge[data-fill="soft"][data-tone="danger"]  { background: var(--destructive-soft);   color: var(--destructive-soft-foreground); }
.badge[data-fill="soft"][data-tone="ai"]      { background: var(--ai-soft);           color: var(--ai-soft-foreground); }
.badge[data-fill="soft"][data-tone="neutral"] { background: var(--muted);       color: var(--muted-foreground); border-color: transparent; }


/* Plain fill — no background/border, just tone-coloured text (e.g. inline metrics). */
.badge[data-fill="plain"] { background: transparent; border-color: transparent; padding-inline: 0; }
.badge[data-fill="plain"][data-tone="neutral"] { color: var(--muted-foreground); }
.badge[data-fill="plain"][data-tone="primary"] { color: var(--primary-accent); }
.badge[data-fill="plain"][data-tone="success"] { color: var(--success-emphasis); }
.badge[data-fill="plain"][data-tone="warning"] { color: var(--warning-emphasis); }
.badge[data-fill="plain"][data-tone="danger"]  { color: var(--destructive-emphasis); }
.badge[data-fill="plain"][data-tone="ai"]      { color: var(--ai); }

import './Badge.css'
import type { HTMLAttributes } from 'react'
import { cn } from '../lib/cn'

type Tone = 'neutral' | 'primary' | 'success' | 'warning' | 'danger' | 'ai'
type Fill = 'solid' | 'soft' | 'plain'
type Size = 'sm' | 'md'

type Props = HTMLAttributes<HTMLSpanElement> & {
  tone?: Tone
  /** Visual fill. `solid` (default) = saturated bg; `soft` = tinted bg + dark text; `plain` = no bg, tone-coloured text. */
  fill?: Fill
  /** `sm` (default) = compact tag; `md` = matches a small button (height + padding). */
  size?: Size
}

/**
 * Status chip: a small standalone pill that labels state through `tone`. Not
 * CountBadge, which pins a number to another element's corner.
 *
 * Copy: one word for a state the reader recognises — "Active", "Overdue". A
 * badge that needs three words is a sentence, and belongs in the body.
 */
export function Badge({ tone = 'neutral', fill, size, className, ...rest }: Props) {
  return (
    <span
      className={cn('badge', className)}
      data-tone={tone}
      data-fill={fill}
      data-size={size}
      {...rest}
    />
  )
}
